"use client";

import { type PointerEvent as ReactPointerEvent, type RefObject, useRef, useState } from "react";
import { type CanvasPoint, type CanvasTransform, zoomAt } from "./canvas-viewport-math";
import { noPanSelector } from "./canvas-viewport-state";

type Options = {
  rootRef: RefObject<HTMLDivElement | null>;
  canPan: boolean;
  disabled: boolean;
  read: () => CanvasTransform;
  apply: (transform: CanvasTransform) => void;
  limits: { minZoom: number; maxZoom: number };
};

const capture = (element: Element, id: number) => {
  try {
    element.setPointerCapture?.(id);
  } catch {
    // The pointer may already have ended.
  }
};

const distance = (a: CanvasPoint, b: CanvasPoint) => Math.hypot(a.x - b.x, a.y - b.y);

/** Drag to pan with a mouse, pen or finger, and pinch with two fingers. */
export function useCanvasGestures({ rootRef, canPan, disabled, read, apply, limits }: Options) {
  const pointers = useRef(new Map<number, CanvasPoint>());
  const gesture = useRef<"pan" | "pinch" | null>(null);
  const [dragging, setDragging] = useState(false);

  const begin = (kind: "pan" | "pinch", element: Element) => {
    gesture.current = kind;
    for (const id of pointers.current.keys()) capture(element, id);
    setDragging(true);
  };

  const onPointerDownCapture = (event: ReactPointerEvent<HTMLDivElement>) => {
    const target = event.target as Element;
    // A portalled popup keeps its React ancestry but owns its pointer actions.
    if (disabled || !event.currentTarget.contains(target)) return;
    const control = !!target.closest(noPanSelector);
    const point = { x: event.clientX, y: event.clientY };
    if (event.pointerType === "touch") {
      if (control && pointers.current.size === 0) return;
      pointers.current.set(event.pointerId, point);
      if (pointers.current.size === 2) begin("pinch", event.currentTarget);
      else if (pointers.current.size === 1 && canPan) begin("pan", event.currentTarget);
      return;
    }
    if (control || !(event.button === 1 || (event.button === 0 && canPan))) return;
    event.preventDefault();
    pointers.current.set(event.pointerId, point);
    begin("pan", event.currentTarget);
  };

  const onPointerMove = (event: ReactPointerEvent<HTMLDivElement>) => {
    const previous = pointers.current.get(event.pointerId);
    if (!previous) return;
    const next = { x: event.clientX, y: event.clientY };
    const other = [...pointers.current].find(([id]) => id !== event.pointerId)?.[1];
    pointers.current.set(event.pointerId, next);
    const current = read();
    if (gesture.current === "pan") {
      apply({ ...current, panX: current.panX + next.x - previous.x, panY: current.panY + next.y - previous.y });
    } else if (gesture.current === "pinch" && other) {
      const bounds = rootRef.current?.getBoundingClientRect();
      const before = distance(previous, other);
      if (!bounds || before === 0) return;
      // The fingers' midpoint stays put while zooming, and moving it pans.
      const middle = { x: (next.x + other.x) / 2 - bounds.left, y: (next.y + other.y) / 2 - bounds.top };
      const zoomed = zoomAt(current, current.zoom * (distance(next, other) / before), middle, limits);
      apply({ ...zoomed, panX: zoomed.panX + (next.x - previous.x) / 2, panY: zoomed.panY + (next.y - previous.y) / 2 });
    }
  };

  const onPointerEnd = (event: ReactPointerEvent<HTMLDivElement>) => {
    if (!pointers.current.delete(event.pointerId)) return;
    // Lifting one finger ends the gesture; the other does nothing until it lifts too.
    gesture.current = null;
    setDragging(false);
  };

  return { dragging, onPointerDownCapture, onPointerMove, onPointerEnd };
}

/** Where the canvas sits: canvas point (x, y) shows at screen point (x * zoom + panX, y * zoom + panY). */
export type CanvasTransform = { panX: number; panY: number; zoom: number };
export type CanvasPoint = { x: number; y: number };
export type CanvasRect = CanvasPoint & { width: number; height: number };
export type CanvasZoomLimits = { minZoom?: number; maxZoom?: number };
export type CanvasFitOptions = CanvasZoomLimits & {
  /** Space kept around the content, in screen pixels. */
  padding?: number;
  /** The closest a fit may zoom in, so small content is not blown up. */
  maxFitZoom?: number;
};

export const defaultMinZoom = 0.1;
export const defaultMaxZoom = 4;

export function clampZoom(zoom: number, { minZoom = defaultMinZoom, maxZoom = defaultMaxZoom }: CanvasZoomLimits = {}) {
  return Math.min(maxZoom, Math.max(minZoom, zoom));
}

/** Zooms around a screen point, so whatever is under it stays under it. */
export function zoomAt(transform: CanvasTransform, nextZoom: number, point: CanvasPoint, limits?: CanvasZoomLimits): CanvasTransform {
  const zoom = clampZoom(nextZoom, limits);
  const ratio = zoom / transform.zoom;
  return { zoom, panX: point.x - (point.x - transform.panX) * ratio, panY: point.y - (point.y - transform.panY) * ratio };
}

/** The transform that shows every rect inside a viewport of the given size. */
export function fitRects(rects: CanvasRect[], viewport: { width: number; height: number }, { padding = 64, maxFitZoom = 1, ...limits }: CanvasFitOptions = {}): CanvasTransform {
  if (rects.length === 0 || viewport.width <= 0 || viewport.height <= 0) return { panX: 0, panY: 0, zoom: 1 };
  const left = Math.min(...rects.map((rect) => rect.x));
  const top = Math.min(...rects.map((rect) => rect.y));
  const width = Math.max(...rects.map((rect) => rect.x + rect.width)) - left;
  const height = Math.max(...rects.map((rect) => rect.y + rect.height)) - top;
  const zoom = clampZoom(Math.min(maxFitZoom, (viewport.width - padding * 2) / Math.max(1, width), (viewport.height - padding * 2) / Math.max(1, height)), limits);
  return { zoom, panX: (viewport.width - width * zoom) / 2 - left * zoom, panY: (viewport.height - height * zoom) / 2 - top * zoom };
}

/** A canvas rect in screen pixels, relative to the viewport. */
export const toScreenRect = (rect: CanvasRect, { panX, panY, zoom }: CanvasTransform): CanvasRect => ({
  x: rect.x * zoom + panX,
  y: rect.y * zoom + panY,
  width: rect.width * zoom,
  height: rect.height * zoom,
});

/** A screen point, relative to the viewport, in canvas units. */
export const toCanvasPoint = (point: CanvasPoint, { panX, panY, zoom }: CanvasTransform): CanvasPoint => ({ x: (point.x - panX) / zoom, y: (point.y - panY) / zoom });

"use client";

import { type ComponentPropsWithoutRef, type ReactNode, forwardRef } from "react";
import { type CanvasRect, toScreenRect } from "./canvas-viewport-math";
import { useCanvasViewport } from "./canvas-viewport-state";
import { cn } from "@/lib/utils";

/** Holds content positioned in canvas units. It moves and scales with the canvas. */
export const CanvasWorld = forwardRef<HTMLDivElement, ComponentPropsWithoutRef<"div">>(function CanvasWorld({ className, style, ...props }, ref) {
  const { transform, canPan } = useCanvasViewport();
  return (
    <div
      ref={ref}
      data-slot="canvas-world"
      data-canvas-content=""
      className={cn("absolute top-0 left-0 origin-top-left", canPan && "pointer-events-none", className)}
      style={{ ...style, transform: `translate(${transform.panX}px, ${transform.panY}px) scale(${transform.zoom})` }}
      {...props}
    />
  );
});

/** Screen-space content above the canvas. It ignores the pointer; give controls inside `pointer-events-auto`. */
export const CanvasOverlay = forwardRef<HTMLDivElement, ComponentPropsWithoutRef<"div">>(function CanvasOverlay({ className, ...props }, ref) {
  return <div ref={ref} data-slot="canvas-overlay" className={cn("pointer-events-none absolute inset-0", className)} {...props} />;
});

type SelectionProps = Omit<ComponentPropsWithoutRef<"div">, "title"> & {
  /** The selected area, in canvas units. */
  rect: CanvasRect;
  /** Shown above the outline, such as the selection's name. */
  title?: ReactNode;
  /** Shown below the outline, such as its size. */
  label?: ReactNode;
  /** Shows the corner marks. They are decorative; resizing belongs to your app. */
  corners?: boolean;
};

// Centres the 6px marks on the outline's corners.
const cornerPositions = ["-top-[3px] -left-[3px]", "-top-[3px] -right-[3px]", "-bottom-[3px] -left-[3px]", "-bottom-[3px] -right-[3px]"];

/** A selection outline in screen space, so its line and corners keep their size at any zoom. Place it in CanvasOverlay. */
export const CanvasSelection = forwardRef<HTMLDivElement, SelectionProps>(function CanvasSelection({ rect, title, label, corners = true, className, style, ...props }, ref) {
  const { transform } = useCanvasViewport();
  const screen = toScreenRect(rect, transform);
  return (
    <div ref={ref} data-slot="canvas-selection" className={cn("absolute border border-primary", className)} style={{ ...style, left: screen.x, top: screen.y, width: screen.width, height: screen.height }} {...props}>
      {title != null && <span className="absolute -top-5 left-0 max-w-full truncate text-[11px] leading-4 text-primary">{title}</span>}
      {corners && cornerPositions.map((position) => <span key={position} aria-hidden className={cn("absolute size-1.5 border border-primary bg-[var(--canvas-selection-fill,#fff)]", position)} />)}
      {label != null && (
        <span className="absolute top-full left-1/2 mt-1.5 -translate-x-1/2 rounded-sm bg-primary px-1.5 py-0.5 text-[10px] leading-3 font-medium whitespace-nowrap text-primary-foreground tabular-nums">{label}</span>
      )}
    </div>
  );
});

type EmptyProps = ComponentPropsWithoutRef<"div"> & {
  /** Replace the icon above the text. */
  icon?: ReactNode;
};

/** Centred in the canvas when your app has nothing to show: an icon with short text below it. */
export const CanvasViewportEmpty = forwardRef<HTMLDivElement, EmptyProps>(function CanvasViewportEmpty({ icon, className, children, ...props }, ref) {
  const { messages } = useCanvasViewport();
  return (
    <div ref={ref} role="status" className={cn("pointer-events-none absolute inset-0 flex flex-col items-center justify-center gap-2.5 px-4 text-center text-sm text-muted-foreground", className)} {...props}>
      <span aria-hidden className="grid size-10 place-items-center rounded-full bg-muted [&_svg]:size-5">
        {icon ?? (
          <svg viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth={1.5} strokeLinecap="round" strokeLinejoin="round">
            <path d="M3 7V4.5A1.5 1.5 0 0 1 4.5 3H7M13 3h2.5A1.5 1.5 0 0 1 17 4.5V7M17 13v2.5a1.5 1.5 0 0 1-1.5 1.5H13M7 17H4.5A1.5 1.5 0 0 1 3 15.5V13" />
          </svg>
        )}
      </span>
      <p className="max-w-52 text-balance">{children ?? messages.empty}</p>
    </div>
  );
});

"use client";

import { type KeyboardEvent, forwardRef, useEffect, useImperativeHandle, useLayoutEffect, useRef, useState } from "react";
import { type CanvasPoint, type CanvasTransform, clampZoom, defaultMaxZoom, defaultMinZoom, fitRects, zoomAt } from "./canvas-viewport-math";
import { useCanvasGestures } from "./canvas-viewport-gestures";
import { type CanvasViewportContextValue, type CanvasViewportProps, CanvasViewportContext, defaultMessages, noPanSelector } from "./canvas-viewport-state";
import { cn } from "@/lib/utils";

const useIsomorphicLayoutEffect = typeof window === "undefined" ? useEffect : useLayoutEffect;
const initialTransform: CanvasTransform = { panX: 0, panY: 0, zoom: 1 };
const keyPan = 40;
const keyZoom = 1.25;

const isTyping = (target: EventTarget | null) => target instanceof HTMLElement && (target.isContentEditable || ["INPUT", "TEXTAREA", "SELECT"].includes(target.tagName));

/**
 * An infinite canvas. The wheel or trackpad pans; pinch or Cmd/Ctrl + wheel zooms around the pointer;
 * the hand tool, Space or the middle button drag it. Put content in CanvasWorld and screen-space UI in CanvasOverlay.
 */
export const CanvasViewport = forwardRef<HTMLDivElement, CanvasViewportProps>(function CanvasViewport(
  {
    transform: transformProp,
    defaultTransform = initialTransform,
    onTransformChange,
    panning = false,
    onPanningChange,
    minZoom = defaultMinZoom,
    maxZoom = defaultMaxZoom,
    disabled = false,
    messages: messagesProp,
    className,
    children,
    onKeyDown,
    onPointerDownCapture,
    onPointerMove,
    onPointerUp,
    onPointerCancel,
    onLostPointerCapture,
    onPointerEnter,
    onPointerLeave,
    ...props
  },
  ref,
) {
  const messages = { ...defaultMessages, ...messagesProp };
  const limits = { minZoom, maxZoom };
  const root = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => root.current as HTMLDivElement);
  const [inner, setInner] = useState(defaultTransform);
  const transform = transformProp ?? inner;
  const [spaceHeld, setSpaceHeld] = useState(false);
  const [announcement, setAnnouncement] = useState("");
  const hovered = useRef(false);
  // Several wheel or pointer events can arrive between renders, so each builds on the last.
  const latest = useRef({ transform, onTransformChange, controlled: transformProp !== undefined, limits });
  useIsomorphicLayoutEffect(() => {
    latest.current = { transform, onTransformChange, controlled: transformProp !== undefined, limits };
  });

  const apply = (next: CanvasTransform) => {
    const { transform: current, controlled, onTransformChange: change } = latest.current;
    if (next.panX === current.panX && next.panY === current.panY && next.zoom === current.zoom) return;
    latest.current.transform = next;
    if (!controlled) setInner(next);
    change?.(next);
  };
  const read = () => latest.current.transform;
  const centre = (): CanvasPoint => ({ x: (root.current?.clientWidth ?? 0) / 2, y: (root.current?.clientHeight ?? 0) / 2 });
  const announce = (zoom: number) => setAnnouncement(messages.zoom(Math.round(zoom * 100)));
  const zoomTo = (zoom: number, point = centre()) => {
    apply(zoomAt(read(), zoom, point, latest.current.limits));
    announce(clampZoom(zoom, latest.current.limits));
  };

  const canPanWithoutDrag = !disabled && (panning || spaceHeld);
  const gestures = useCanvasGestures({ rootRef: root, canPan: canPanWithoutDrag, disabled, read, apply, limits });
  const canPan = canPanWithoutDrag || gestures.dragging;
  const ownsPointer = !disabled && (panning || gestures.dragging);

  useEffect(() => {
    const element = root.current;
    if (!element || disabled) return;
    const onWheel = (event: WheelEvent) => {
      event.preventDefault();
      const scale = event.deltaMode === WheelEvent.DOM_DELTA_LINE ? 16 : 1;
      const current = latest.current.transform;
      if (event.ctrlKey || event.metaKey) {
        const bounds = element.getBoundingClientRect();
        apply(zoomAt(current, current.zoom * Math.exp(-event.deltaY * scale * 0.01), { x: event.clientX - bounds.left, y: event.clientY - bounds.top }, latest.current.limits));
      } else {
        apply({ ...current, panX: current.panX - event.deltaX * scale, panY: current.panY - event.deltaY * scale });
      }
    };
    element.addEventListener("wheel", onWheel, { passive: false });
    return () => element.removeEventListener("wheel", onWheel);
    // apply reads everything it needs from refs.
  }, [disabled]);

  useEffect(() => {
    if (disabled) return;
    const down = (event: globalThis.KeyboardEvent) => {
      if (event.code !== "Space" || isTyping(event.target)) return;
      // Only the canvas under the pointer or holding focus responds, so several can share a page.
      if (!hovered.current && !root.current?.contains(document.activeElement)) return;
      setSpaceHeld(true);
      if (!(event.target instanceof Element && event.target.closest(noPanSelector))) event.preventDefault();
    };
    const up = (event: globalThis.KeyboardEvent) => {
      if (event.code === "Space") setSpaceHeld(false);
    };
    const blur = () => setSpaceHeld(false);
    // Capture, so a focused control that stops the key cannot hide it.
    window.addEventListener("keydown", down, true);
    window.addEventListener("keyup", up, true);
    window.addEventListener("blur", blur);
    return () => {
      window.removeEventListener("keydown", down, true);
      window.removeEventListener("keyup", up, true);
      window.removeEventListener("blur", blur);
      setSpaceHeld(false);
    };
  }, [disabled]);

  const reported = useRef(false);
  useIsomorphicLayoutEffect(() => {
    if (reported.current === ownsPointer) return;
    reported.current = ownsPointer;
    onPanningChange?.(ownsPointer);
  }, [ownsPointer, onPanningChange]);

  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    onKeyDown?.(event);
    if (event.defaultPrevented || disabled || event.target !== event.currentTarget) return;
    const step = event.shiftKey ? keyPan * 4 : keyPan;
    const current = read();
    const pans: Record<string, [number, number]> = { ArrowLeft: [step, 0], ArrowRight: [-step, 0], ArrowUp: [0, step], ArrowDown: [0, -step] };
    const pan = pans[event.key];
    if (pan) apply({ ...current, panX: current.panX + pan[0], panY: current.panY + pan[1] });
    else if (event.key === "+" || event.key === "=") zoomTo(current.zoom * keyZoom);
    else if (event.key === "-") zoomTo(current.zoom / keyZoom);
    else if (event.key === "0") zoomTo(1);
    else return;
    event.preventDefault();
  };

  const context: CanvasViewportContextValue = {
    transform,
    setTransform: apply,
    zoomTo,
    zoomBy: (factor, point) => zoomTo(read().zoom * factor, point),
    fit: (rects, options) => {
      const size = { width: root.current?.clientWidth ?? 0, height: root.current?.clientHeight ?? 0 };
      const next = fitRects(rects, size, { ...latest.current.limits, ...options });
      apply(next);
      announce(next.zoom);
    },
    canPan,
    dragging: gestures.dragging,
    disabled,
    messages,
  };

  return (
    <CanvasViewportContext.Provider value={context}>
      <div
        ref={root}
        role="group"
        aria-label={messages.label}
        aria-roledescription={messages.roleDescription}
        aria-disabled={disabled || undefined}
        tabIndex={disabled ? undefined : 0}
        data-slot="canvas-viewport"
        data-panning={canPan || undefined}
        data-dragging={gestures.dragging || undefined}
        data-disabled={disabled || undefined}
        className={cn(
          "relative isolate touch-none overflow-hidden bg-muted outline-none select-none",
          canPan && (gestures.dragging ? "cursor-grabbing" : "cursor-grab"),
          className,
        )}
        {...props}
        onKeyDown={handleKeyDown}
        onPointerEnter={(event) => {
          hovered.current = true;
          onPointerEnter?.(event);
        }}
        onPointerLeave={(event) => {
          hovered.current = false;
          onPointerLeave?.(event);
        }}
        onPointerDownCapture={(event) => {
          onPointerDownCapture?.(event);
          gestures.onPointerDownCapture(event);
        }}
        onPointerMove={(event) => {
          onPointerMove?.(event);
          gestures.onPointerMove(event);
        }}
        onPointerUp={(event) => {
          onPointerUp?.(event);
          gestures.onPointerEnd(event);
        }}
        onPointerCancel={(event) => {
          onPointerCancel?.(event);
          gestures.onPointerEnd(event);
        }}
        onLostPointerCapture={(event) => {
          onLostPointerCapture?.(event);
          // Pinching can move implicit touch capture from a child to this viewport.
          if (event.target === event.currentTarget) gestures.onPointerEnd(event);
        }}
      >
        {children}
        <p aria-live="polite" className="sr-only">
          {announcement}
        </p>
      </div>
    </CanvasViewportContext.Provider>
  );
});

"use client";

import { type ComponentPropsWithoutRef, createContext, useContext } from "react";
import type { CanvasFitOptions, CanvasPoint, CanvasRect, CanvasTransform } from "./canvas-viewport-math";

/** Replaceable text, for example to translate. */
export type CanvasViewportMessages = {
  label: string;
  roleDescription: string;
  empty: string;
  zoom: (percent: number) => string;
};

export const defaultMessages: CanvasViewportMessages = {
  label: "Canvas",
  roleDescription: "canvas",
  empty: "Nothing on the canvas yet.",
  zoom: (percent) => `Zoom ${percent}%`,
};

export type CanvasViewportProps = ComponentPropsWithoutRef<"div"> & {
  /** Where the canvas sits, when your app owns it. */
  transform?: CanvasTransform;
  /** Where the canvas starts when your app does not own it. */
  defaultTransform?: CanvasTransform;
  onTransformChange?: (transform: CanvasTransform) => void;
  /** Drag anywhere to pan, as with a hand tool. Space or the middle button pan at any time. */
  panning?: boolean;
  /** Reports whether the canvas owns the pointer: the hand tool, or a pan in progress. Holding Space alone does not count. */
  onPanningChange?: (panning: boolean) => void;
  minZoom?: number;
  maxZoom?: number;
  /** Turns off panning and zooming. */
  disabled?: boolean;
  messages?: Partial<CanvasViewportMessages>;
};

export type CanvasViewportContextValue = {
  transform: CanvasTransform;
  setTransform: (transform: CanvasTransform) => void;
  /** Zooms to a level, around a screen point or the viewport's centre. */
  zoomTo: (zoom: number, point?: CanvasPoint) => void;
  /** Multiplies the zoom, around a screen point or the viewport's centre. */
  zoomBy: (factor: number, point?: CanvasPoint) => void;
  /** Shows every rect, given in canvas units. */
  fit: (rects: CanvasRect[], options?: CanvasFitOptions) => void;
  /** Dragging would pan right now. */
  canPan: boolean;
  dragging: boolean;
  disabled: boolean;
  messages: CanvasViewportMessages;
};

export const CanvasViewportContext = createContext<CanvasViewportContextValue | null>(null);

/** State and actions of the nearest CanvasViewport, for zoom controls and custom parts. */
export function useCanvasViewport() {
  const context = useContext(CanvasViewportContext);
  if (!context) throw new Error("Canvas parts must be rendered inside <CanvasViewport>.");
  return context;
}

/** Pressing these never starts a pan, so controls on the canvas keep working. */
export const noPanSelector = 'button, input, textarea, select, a[href], [contenteditable="true"], [data-canvas-no-pan]';

"use client";

export { type CanvasViewportProps, type CanvasViewportMessages, useCanvasViewport } from "./canvas-viewport-state";
export { CanvasViewport } from "./canvas-viewport-root";
export { CanvasWorld, CanvasOverlay, CanvasSelection, CanvasViewportEmpty } from "./canvas-viewport-parts";
export { type CanvasTransform, type CanvasPoint, type CanvasRect, type CanvasFitOptions, clampZoom, zoomAt, fitRects, toScreenRect, toCanvasPoint } from "./canvas-viewport-math";
